    /// <summary>
    /// Finds the specified record in the <c>METCustomerOperationsGroup</c> table.
    /// </summary>
    /// <param name="_custGroupId">
    /// The CustomerOperationsGroup of the <c>METCustomerOperationsGroup</c> record to find.
    /// </param>
    /// <param name="_forupdate">
    /// A Boolean value that indicates whether to read the record for update; optional.
    /// </param>
    /// <param name="_concurrencyModel">
    /// The ConcurrencyModel value set to; Auto.
    /// </param>
    /// <returns>
    /// A record in the <c>METCustomerOperationsGroup</c> table; otherwise, an empty record.
    /// </returns>
    public static METCustomerOperationsGroup find(
        METCustOperGroupId _custGroupId ,
        boolean _forupdate = false,
        ConcurrencyModel _concurrencyModel = ConcurrencyModel::Auto)
    {
        METCustomerOperationsGroup custGroup;

        custGroup.selectForUpdate(_forupdate);
        if (_forupdate && _concurrencyModel != ConcurrencyModel::Auto)
        {
            custGroup.concurrencyModel(_concurrencyModel);
        }

        select firstonly custGroup where custGroup.CustomerOperationsGroup == _custGroupId;

        return custGroup;
    }

    /// <summary>
    /// Exists the specified record in the <c>METCustomerOperationsGroup</c> table.
    /// </summary>
    /// <param name = "_custGroupId">
    /// The CustomerOperationsGroup of the <c>METCustomerOperationsGroup</c> record to exists.
    /// </param>
    /// <returns>A Boolean value that indicates whether the record exists or not</returns>
    public static boolean exist(METCustOperGroupId _custGroupId)
    {
        boolean found;

        found = (select firstonly
                     RecId
                from
                     METCustomerOperationsGroup
                 where
                     METCustomerOperationsGroup.CustomerOperationsGroup == _custGroupId).RecId != 0;

        return found;
    }
